function listPage(tasks, query) {
	const fail = (code, message) => ({ status: 400, body: { error: { code, message } } });
	const rawLimit = query.get("limit");
	const limit = rawLimit === null ? 25 : Number(rawLimit);
	if (!Number.isInteger(limit) || limit < 1 || limit > 50) {
		return fail("invalid_limit", "limit must be an integer from 1 to 50");
	}
	const status = query.get("status");
	if (status !== null && status !== "open" && status !== "done") {
		return fail("invalid_status", "status must be open or done");
	}
	let after = null;
	if (query.has("cursor")) {
		const token = query.get("cursor");
		try {
			if (!token || !/^[A-Za-z0-9_-]+$/.test(token)) throw new Error();
			const bytes = Buffer.from(token, "base64url");
			if (bytes.toString("base64url") !== token) throw new Error();
			const cursor = JSON.parse(bytes.toString("utf8"));
			if (!Array.isArray(cursor) || cursor.length !== 3 || cursor[0] !== 1 ||
				typeof cursor[1] !== "string" || !cursor[1] || cursor[2] !== status) throw new Error();
			after = cursor[1];
		} catch {
			return fail("invalid_cursor", "cursor is invalid for this query");
		}
	}
	const eligible = [...tasks].filter(task => !task.deleted_at &&
		(status === null || task.status === status) && (after === null || task.id > after));
	eligible.sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
	const page = eligible.slice(0, limit);
	const items = page.map(task => ({ ...task }));
	const next_cursor = eligible.length > limit
		? Buffer.from(JSON.stringify([1, page[page.length - 1].id, status])).toString("base64url")
		: null;
	return { status: 200, body: { items, next_cursor } };
}
